def section(lang):
    b = []

    b.append(H("13.9 Tính chất của hơi quá nhiệt",
               "13.9 Properties of Superheated Steam", lang))
    b.append(LEAD(
        "ʋ = thể tích riêng, feet khối trên pound; hg = nhiệt tổng của hơi, "
        "BTU trên pound. Nhiệt độ tổng (t) được tính theo °F. Các dòng tiêu đề "
        "nhóm cho biết dải nhiệt độ tổng áp dụng cho các dòng số liệu bên dưới.",
        "ʋ = specific volume, cubic feet per pound; hg = total heat of steam, "
        "BTU per pound. Total Temperature (t) is given in °F. The band rows "
        "state the total-temperature set that applies to the rows beneath them.",
        lang))

    b.append(P(
        "Bảng gồm sáu cột Nhiệt độ tổng (t) (°F); mỗi cột cho một cặp giá trị "
        "thể tích riêng ʋ và nhiệt tổng hg.",
        "This table has six Total Temperature (t) (°F) columns; each column "
        "gives a pair of specific volume ʋ and total heat hg values.", lang))
    b.append(TB(_H6_VI, _H6_EN, _V6, lang,
                cap_vi="Bảng 13.9 — Tính chất của hơi quá nhiệt (sáu cột nhiệt độ tổng, "
                       "360°–800°F).",
                cap_en="Table 13.9 — Properties of Superheated Steam (six total-"
                       "temperature columns, 360°–800°F)."))

    b.append(P(
        "Bảng gồm năm cột Nhiệt độ tổng (t) (°F), tiếp nối bảng trên theo "
        "thứ tự áp suất của nguồn.",
        "This table has five Total Temperature (t) (°F) columns, continuing "
        "the source table in its original pressure order.", lang))
    b.append(TB(_H5_VI, _H5_EN, _V5, lang,
                cap_vi="Bảng 13.9 (tiếp theo) — Tính chất của hơi quá nhiệt "
                       "(năm cột nhiệt độ tổng, 700°–1200°F).",
                cap_en="Table 13.9 (continued) — Properties of Superheated Steam "
                       "(five total-temperature columns, 700°–1200°F)."))

    b.append(N(
        "Ghi chú về nguồn: “- - -” biểu thị giá trị không áp dụng ở áp suất đó. "
        "Một số giá trị giữ nguyên lỗi OCR của bản in: “1233.” (dòng 60.0), "
        "“1266.90” (dòng 120.0) và “07967” (dòng 1200.0). Mọi số liệu đều "
        "được sao chép nguyên vẹn, không làm tròn hay lược bỏ.",
        "Source note: “- - -” marks values not applicable at the given "
        "pressure. Several OCR spellings are kept as printed: “1233.” "
        "(60.0 row), “1266.90” (120.0 row) and “07967” (1200.0 row). All "
        "figures are transcribed verbatim, with no rounding or omission.", lang))

    return "".join(b)
